1	// JusPrin's Preferences window (canvas "JusPrin v2", Preferences, decided
2	// 2026-10-21): a list of sections on the left and the chosen one beside it.
3	// The app reads and writes every setting, under the keys OrcaSlicer's own
4	// dialog uses, and sends what is stored after each change; the page only
5	// says what to change. The Agent section is where the agent is set up, the
6	// first time too: every surface that finds no agent opens it there
7	// (decided 2026-10-23). Agent and Account draw the connection rows of
8	// AgentConnection.tsx.
9	
10	import { useEffect, useState } from 'react';
11	import {
12	  AccountStatusPayload,
13	  CreditAccount,
14	  DragAction,
15	  McpCatalogPayload,
16	  McpPreviewPayload,
17	  McpStatusPayload,
18	  McpToolInfo,
19	  PreferencesPayload,
20	  PreferencesSection,
21	  SavedKeyInfo,
22	  SetupStatusPayload,
23	} from '../bridge/protocol';
24	import { AccountBox } from './AccountBox';
25	import { AccountRow, ProviderKeys, ToolGroup } from './AgentConnection';
26	import { balanceRows } from './BalancePanel';
27	import { creditCount, creditNumber, TIER_NAMES } from '../credits';
28	import { MarkdownMessage } from './MarkdownMessage';
29	import { Progress } from './Progress';
30	import { ActionMenu } from './ChatNavigation';
31	import { SetupLocalTool } from './SetupLocalTool';
32	
33	const SECTIONS: { id: PreferencesSection; label: string; icon: string }[] = [
34	  { id: 'account', label: 'Account', icon: 'user' },
35	  { id: 'agent', label: 'AI', icon: 'bot' },
36	  { id: 'appearance', label: 'Appearance', icon: 'palette' },
37	  { id: 'view3d', label: '3D view', icon: 'box' },
38	  { id: 'projects', label: 'Projects & files', icon: 'folder' },
39	  { id: 'updates', label: 'Updates', icon: 'refresh-cw' },
40	];
41	
42	// What each mouse button's drag can do, in OrcaSlicer's order.
43	const DRAG_ACTIONS: { value: DragAction; label: string }[] = [
44	  { value: 'rotate', label: 'Turn the view' },
45	  { value: 'pan', label: 'Pan' },
46	  { value: 'none', label: 'Nothing' },
47	];
48	
49	export interface PreferencesActions {
50	  // One setting, by the name the app's settings use.
51	  set: (name: string, value: string | boolean) => void;
52	  // A command: choose_downloads, show_versions, open_update, check_updates,
53	  // skip_update (with the version), restart, orca_preferences.
54	  run: (action: string, details?: Record<string, string>) => void;
55	  checkKey: (provider: string, apiKey: string) => void;
56	  cancelCheck: () => void;
57	  removeKey: (provider: string) => void;
58	  refreshTools: () => void;
59	  previewTool: (toolId: string) => void;
60	  connectTool: (toolId: string) => void;
61	  revealTool: (toolId: string) => void;
62	  signIn: () => void;
63	  cancelSignIn: () => void;
64	  getMoreCredits: () => void;
65	  refreshAccountBox: () => void;
66	}
67	
68	export interface PreferencesProps {
69	  preferences: PreferencesPayload;
70	  setup: SetupStatusPayload;
71	  savedKeys: SavedKeyInfo[];
72	  account: AccountStatusPayload;
73	  // The signed-in account's credits and usage; null with no account or
74	  // before it answers.
75	  creditAccount: CreditAccount | null;
76	  chatTitles: Record<string, string>;
77	  // The box the server fills near the top of Account; null for none.
78	  accountBox: string | null;
79	  mcpCatalog: McpCatalogPayload | null;
80	  mcpPreview: McpPreviewPayload | null;
81	  mcpStatus: McpStatusPayload;
82	  actions: PreferencesActions;
83	  // Done on an AI tool, for a window opened to close once one is connected.
84	  onToolDone?: () => void;
85	}
86	
87	// The JusPrin account row, as Account and Agent both draw it.
88	function JusPrinAccount({ savedKeys, account, actions }: {
89	  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; actions: PreferencesActions;
90	}) {
91	  return (
92	    <AccountRow account={savedKeys.find((key) => key.provider === 'jusprin')} status={account} onSignIn={actions.signIn}
93	      onCancel={actions.cancelSignIn} onSignOut={() => actions.removeKey('jusprin')} />
94	  );
95	}
96	
97	function Row({ title, detail, children }: { title: string; detail?: React.ReactNode; children?: React.ReactNode }) {
98	  return (
99	    <div className="prefs-row">
100	      <div className="prefs-row-copy">
101	        <span className="prefs-row-title">{title}</span>
102	        {detail && <span className="prefs-row-detail">{detail}</span>}
103	      </div>
104	      {children}
105	    </div>
106	  );
107	}
108	
109	function Check({ title, detail, checked, onChange }: {
110	  title: string; detail: string; checked: boolean; onChange: (checked: boolean) => void;
111	}) {
112	  return (
113	    <div className="prefs-row">
114	      <button type="button" role="checkbox" aria-checked={checked} className="printer-form-check prefs-check"
115	        onClick={() => onChange(!checked)}>
116	        <span className="printer-form-check-box">{checked && <span className="jp-icon jp-icon-check" aria-hidden="true" />}</span>
117	        <span className="printer-form-check-copy">
118	          <span>{title}</span>
119	          <span className="printer-form-check-detail">{detail}</span>
120	        </span>
121	      </button>
122	    </div>
123	  );
124	}
