126	function Segmented<T extends string>({ label, options, value, onChange }: {
127	  label: string; options: { value: T; label: string }[]; value: T; onChange: (value: T) => void;
128	}) {
129	  return (
130	    <div className="jp-segmented prefs-segmented" role="radiogroup" aria-label={label}>
131	      {options.map((option) => (
132	        <button key={option.value} type="button" role="radio" aria-checked={option.value === value}
133	          className={option.value === value ? 'jp-segment selected' : 'jp-segment'} onClick={() => onChange(option.value)}>
134	          {option.label}
135	        </button>
136	      ))}
137	    </div>
138	  );
139	}
140	
141	function Select<T extends string>({ label, options, value, onChange, searchable = false }: {
142	  label: string; options: { value: T; label: string }[]; value: T; onChange: (value: T) => void; searchable?: boolean;
143	}) {
144	  return (
145	    <div className="prefs-select">
146	      <ActionMenu
147	        appearance="select"
148	        label={label}
149	        text={options.find((option) => option.value === value)?.label ?? value}
150	        items={options.map((option) => ({
151	          key: option.value,
152	          label: option.label,
153	          current: option.value === value,
154	          onSelect: () => { if (option.value !== value) onChange(option.value); },
155	        }))}
156	        search={searchable ? { label: `Find a ${label.toLowerCase()}`, noMatch: (query) => `No ${label.toLowerCase()} matches “${query}”` } : undefined}
157	      />
158	    </div>
159	  );
160	}
161	
162	function Group({ title, tag, children }: { title: string; tag?: string; children: React.ReactNode }) {
163	  return (
164	    <div className="prefs-group">
165	      <div className="prefs-group-head">
166	        <h3 className="prefs-group-title">{title}</h3>
167	        {tag && <span className="prefs-group-tag">{tag}</span>}
168	      </div>
169	      {children}
170	    </div>
171	  );
172	}
