174	// A gateway day, YYYY-MM-DD, as "5 Nov". The day is the gateway's, so it is
175	// read as UTC: a local reading would move it a day west of Greenwich.
176	function dayLabel(date: string): string {
177	  return new Date(`${date}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
178	}
179	
180	const USAGE_DAYS = 30;
181	// Rows shown before "See all activity".
182	const ACTIVITY_ROWS = 5;
183	
184	// The 30 days the usage covers, oldest first, today last.
185	function usageDays(now: Date): string[] {
186	  return Array.from({ length: USAGE_DAYS }, (_, index) =>
187	    new Date(now.getTime() - (USAGE_DAYS - 1 - index) * 86_400_000).toISOString().slice(0, 10));
188	}
189	
190	// The account's plan, credits and usage (boards 4a to 4c on the canvas's
191	// "Agent setup & Preferences" page): a bar for each kind of credit as the
192	// composer's panel draws them, then usage per day with totals per chat.
193	function AccountCredits({ account, chatTitles, onGetMore }: {
194	  account: CreditAccount; chatTitles: Record<string, string>; onGetMore: () => void;
195	}) {
196	  const [allActivity, setAllActivity] = useState(false);
197	  const usage = account.usage_30d;
198	  const byDay = new Map(usage.days.map((day) => [day.date, day.credits]));
199	  const days = usageDays(new Date());
200	  const most = Math.max(0, ...days.map((day) => byDay.get(day) ?? 0));
201	  const activity = allActivity ? usage.activity : usage.activity.slice(0, ACTIVITY_ROWS);
202	  return (
203	    <>
204	      <div className="prefs-credits-plan">
205	        <div className="prefs-row-copy">
206	          <span className="prefs-credits-plan-name">{account.plan?.name ?? 'Pay as you go'}</span>
207	          <span className="prefs-intro">
208	            {account.plan
209	              ? (account.plan.renews_at ? `Renews ${dayLabel(account.plan.renews_at.slice(0, 10))}.` : '')
210	              : 'Only messages you send cost credits.'}
211	          </span>
212	        </div>
213	        <button type="button" className="primary" onClick={onGetMore}>Get more credits</button>
214	      </div>
215	      <div className="prefs-credits">
216	        <div className="prefs-credits-card">
217	          <strong className="prefs-credits-total">{creditCount(account.credits.total)} left</strong>
218	          {balanceRows(account).map((row) => (
219	            <div key={row.key} className="credit-lot prefs-credits-lot">
220	              <div className="credit-lot-line">
221	                <strong>{row.name}</strong>
222	                <span>{creditNumber(row.left)} of {creditNumber(row.of)} left</span>
223	              </div>
224	              <div className="credit-lot-bar">
225	                <div className="credit-lot-fill" style={{ width: `${row.of > 0 ? Math.min(row.left / row.of, 1) * 100 : 0}%` }} />
226	              </div>
227	              <span className="credit-lot-date">{row.date}</span>
228	            </div>
229	          ))}
230	        </div>
231	        <p className="prefs-note">Expiring credits are used first.</p>
232	      </div>
233	      <div className="prefs-usage" aria-label="Usage" role="group">
234	        <h3 className="prefs-group-title">Usage</h3>
235	        <div className="prefs-row-copy">
236	          <span className="prefs-credits-plan-name">{creditCount(usage.credits)}</span>
237	          <span className="prefs-note">in the last 30 days</span>
238	        </div>
239	        <div className="prefs-usage-chart">
240	          <div className="prefs-usage-bars">
241	            {days.map((day) => {
242	              const credits = byDay.get(day) ?? 0;
243	              return <div key={day} className="prefs-usage-bar" title={`${dayLabel(day)}: ${creditCount(credits)}`}
244	                style={{ height: `${most > 0 ? (credits / most) * 100 : 0}%` }} />;
245	            })}
246	            {most > 0 && <span className="prefs-usage-most">{creditNumber(most)}</span>}
247	          </div>
248	          <div className="prefs-usage-axis">
249	            <span>{dayLabel(days[0])}</span>
250	            <span>{dayLabel(days[Math.floor(USAGE_DAYS / 2)])}</span>
251	            <span>{dayLabel(days[USAGE_DAYS - 1])}</span>
252	          </div>
253	        </div>
254	        {usage.activity.length > 0 ? (
255	          <table className="prefs-usage-table">
256	            <thead>
257	              <tr><th>Date</th><th>Chat</th><th>Tier</th><th>Messages</th><th>Credits</th></tr>
258	            </thead>
259	            <tbody>
260	              {activity.map((row, index) => 'kind' in row ? (
261	                <tr key={index}>
262	                  <td>{dayLabel(row.date)}</td><td>{row.title}</td><td /><td /><td>+{creditNumber(row.credits)}</td>
263	                </tr>
264	              ) : (
265	                <tr key={index}>
266	                  <td>{dayLabel(row.date)}</td>
267	                  <td>{(row.chat_id !== null && chatTitles[row.chat_id]) || 'A chat not on this computer'}</td>
268	                  <td>{TIER_NAMES[row.tier]}</td>
269	                  <td>{creditNumber(row.messages)}</td>
270	                  <td>{creditNumber(row.credits)}</td>
271	                </tr>
272	              ))}
273	            </tbody>
274	          </table>
275	        ) : (
276	          <p className="prefs-note">No messages in the last 30 days.</p>
277	        )}
278	        {!allActivity && usage.activity.length > ACTIVITY_ROWS && (
279	          <button type="button" className="link prefs-inline-link" onClick={() => setAllActivity(true)}>See all activity</button>
280	        )}
281	      </div>
282	    </>
283	  );
284	}
