286	function AccountSection({ savedKeys, account, creditAccount, chatTitles, accountBox, actions, onAgent }: {
287	  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; creditAccount: CreditAccount | null;
288	  chatTitles: Record<string, string>; accountBox: string | null; actions: PreferencesActions; onAgent: () => void;
289	}) {
290	  const signedIn = savedKeys.some((key) => key.provider === 'jusprin');
291	  // On the person's own API key there is no account to offer anything for.
292	  const ownKey = !signedIn && savedKeys.length > 0;
293	  // The server's box is asked for when Account opens, after a sign-in or
294	  // out, and on coming back from the browser, where a pack may have been
295	  // bought.
296	  useEffect(() => {
297	    if (ownKey)
298	      return;
299	    actions.refreshAccountBox();
300	    const refresh = () => actions.refreshAccountBox();
301	    window.addEventListener('focus', refresh);
302	    return () => window.removeEventListener('focus', refresh);
303	    // eslint-disable-next-line react-hooks/exhaustive-deps
304	  }, [signedIn, ownKey]);
305	  return (
306	    <section className="prefs-section prefs-account" aria-label="Account">
307	      <h2 className="prefs-title">Account</h2>
308	      {!ownKey && accountBox && <AccountBox key={accountBox} html={accountBox} />}
309	      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
310	      {signedIn && creditAccount && (
311	        <AccountCredits account={creditAccount} chatTitles={chatTitles} onGetMore={actions.getMoreCredits} />
312	      )}
313	      {signedIn ? (
314	        <p className="prefs-note">Signing out keeps your projects, printers and API keys on this computer.</p>
315	      ) : (
316	        <p className="prefs-note">
317	          Local work never needs an account. Your own API key or AI tool works without one; set those up in the{' '}
318	          <button type="button" className="link prefs-inline-link" onClick={onAgent}>AI</button> section.
319	        </p>
320	      )}
321	    </section>
322	  );
323	}
