339	      </div>
340	      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
341	      <ProviderKeys heading setup={setup} savedKeys={savedKeys} onCheck={actions.checkKey} onCancel={actions.cancelCheck}
342	        onRemove={actions.removeKey} />
343	      <ToolGroup heading tools={mcpCatalog?.tools ?? []} onConnect={onConnectTool} onLookAgain={actions.refreshTools} />
344	      <Group title="New chats start with">
345	        {agent.newChatChoices.length > 0 ? (
346	          <Row title="Model" detail="A chat keeps the model it started with.">
347	            <Select label="Model" value={agent.newChatProvider} onChange={(provider) => actions.set('newChatProvider', provider)}
348	              options={agent.newChatChoices.map((choice) => ({ value: choice.provider, label: `${choice.model} · ${choice.label}` }))} />
349	          </Row>
350	        ) : (
351	          <Row title="Model" detail="Add a key above, and new chats start with that provider’s model." />
352	        )}
353	      </Group>
354	      <div className="prefs-callout">
355	        <span className="jp-icon jp-icon-lock" aria-hidden="true" />
356	        <p>
357	          The provider a chat uses receives your messages, the open project’s settings and anything you attach. With a
358	          JusPrin account, JusPrin receives them and passes them on to the model provider it uses. JusPrin doesn’t send
359	          your keys anywhere else.
360	        </p>
361	      </div>
362	    </section>
363	  );
364	}
